import numpy as np, json
from collections import Counter
def f(gi):
    gi=np.array(gi); H,W=gi.shape
    vals=Counter(gi.flat); bg=int(vals.most_common(1)[0][0])
    out=gi.copy()
    for i in range(H):
        for j in range(W):
            if int(gi[i,j])!=bg: continue
            R=set(int(x) for x in gi[i,:])-{bg}
            C=set(int(x) for x in gi[:,j])-{bg}
            s=R|C
            out[i,j]=list(s)[0] if len(s)==1 else 2
    return out
print(json.dumps(f(G['Test input'])))
